source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]

    # Uniform horizontal bands encode a cycle indexed by row.
    solid_rows = {r: row[0] for r, row in enumerate(grid) if row[0] and all(x == row[0] for x in row)}
    if solid_rows and all(all(v == 0 for v in grid[r]) or r in solid_rows for r in range(h)):
        period = len(solid_rows)
        by_residue = {r % period: color for r, color in solid_rows.items()}
        if len(by_residue) == period:
            return [[by_residue[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal strokes are constant on c-r. Repeat their colors periodically.
    diag = {}
    for r, c, v in points:
        d = c - r
        if d in diag and diag[d] != v:
            break
        diag[d] = v
    else:
        for period in range(1, max(h, w) + 1):
            residues = {}
            valid = True
            for d, color in diag.items():
                k = d % period
                if k in residues and residues[k] != color:
                    valid = False
                    break
                residues[k] = color
            if valid and len(residues) == period:
                return [[residues[(c-r) % period] for c in range(w)] for r in range(h)]
    return [row[:] for row in grid]
'''
